html:
{% set employee = frappe.get_doc("Employee" , doc.employee) %}
{% set dt = frappe.utils.getdate(doc.submission_datetime) %}
{% set fy_start = dt.year if dt.month >= 4 else dt.year - 1 %}
{%set course = frappe.get_doc("LMS Course", doc.course) %}
{% set template = frappe.call("lms.overrides.documents.get_employee_declaration_template", employee_doc=employee, course_name=doc.course, course_title=course.title) %}
{% set company_name = template['company'] if template else employee.company %}

<div class="certificate">
  <div class="logo-container">
    <div class="logo-left-margin"></div>
    <div class="logo">
      <img class="meril" src="/assets/lms/images/meril.svg" alt="Meril" />
      <span>More to Life</span>
    </div>
  </div>
  <div class="padding-container">
  <h2><i>Certificate of Completion</i></h2>
  {% if company_name %}
    <h3 class="company">for {{ company_name }},</h3>
  {% endif %}
      <span class="addressing">This is hebery presented to</span>
      <p class="emp-name">{{ employee.employee_name }}</p>
      <span class="reasion">for completion of trainning on</span>
    <span class="time">"{{ course.title }}" for FY. {{ fy_start }} - {{ fy_start + 1 }}</span>
    </div>

  <div class="strip strip-tl">
  </div>
   <div class="strip strip-rb">
        <svg width="200px" height="15px">
        <path
        fill="#387d9c"
        d="m0 0 h200 l-15 15 h-185 v-15"
        ></path>
</svg>
  </div>
</div>

<style>
     @page {
    size: A5 landscape;
    margin: 0px;
  }
    @font-face{
        font-family: certificateFont;
        src: url("{{frappe.utils.get_url()}}/assets/lms/fonts/certificate_title.otf");
    }
  * {
    padding: 0;
    margin: 0;
  }

  .certificate {
    background: white;
    position: relative;
    overflow: hidden;
  }

  h2 {
    font-size: 35px;
    text-align: center;
    font-family:  certificateFont ,serif !important;
  }

  .company {
    text-align: center;
    font-size: 20px;
    margin-top: 5px;
    font-family: "Times New Roman", serif;
    font-style: italic;
  }

  .logo-container {
    width: 100%;
    display: -webkit-box;
    display: flex;
    flex-direction: row;
    padding: 0;
    margin: 0;

  }

  .logo-left-margin {
    flex: 1;
    -webkit-box-flex: 1;
    height: 100px;

  }

  .logo {
    display: block;
    width: fit-content;
    margin-left: auto;
    position: relative;

  }

  .print-format {
    margin: 0;
    padding: 0;
  }

  .logo span {
    position: absolute;
    bottom: 0;
    transform: translate(-50%, -80%);
     -webkit-transform: translate(-50%, -65%);
    left: 50%;
    white-space: nowrap;
    font-family: sans-serif;
    color: #999;

  }

  .meril {
    width: 130px;
    font-family: sans-serif;

  }

  .padding-container {
    padding: 0 100px 100px;
  }

  .addressing,
  .emp-name,
  .reasion,
  .time {
    font-size: 19px;
    font-family: sans-serif;
    display: block;
  }

  .addressing {
    margin-top: 30px;
    color: #42505d;
  }

  .emp-name {
    text-align: center;
    padding: 10px 0px;

  }

  .strip {
    position: absolute;
    width: 250px;
    height: 250px;
    background: -webkit-linear-gradient(left, #16668b 85%, #387d9c 85%);
    background: linear-gradient(to right, #16668b 85%, #387d9c 85%);
  }

  .strip-tl {
    top: 0;
    left: 0;
    transform: translate(-50%, -50%) rotate(45deg);
    -webkit-transform: translate(-50%, -50%) rotate(45deg);
  }

  .strip-rb {
    right: 0;
    bottom: 0;
    transform: translate(50%, 50%) rotate(225deg);
    -webkit-transform: translate(50%, 50%) rotate(225deg);
  }

  .strip > svg{
   -webkit-transform: translate(83%, 440%) rotateY(180deg) rotateZ(90deg);
  }

</style>
